package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TenantsSketchVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property tenants sketch of observed issue ")
  void test_tenants_sketch_v_o_builder() {
    Assertions.assertFalse(TenantsSketchVO.nullValue().getTenantsSketch().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(TenantsSketchVO.tryFrom(null).getTenantsSketch().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", TenantsSketchVO.from("one").getTenantsSketch().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> TenantsSketchVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TenantsSketchVO.from("one").toString());
  }
}
